WITH flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessions_payments AS (SELECT id, order_id, method, paid_at, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT method, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, SUM(CASE WHEN method = 'bank_transfer' THEN burst_id ELSE 0 END) AS bank_transfer_burst_id, MAX(burst_id) FILTER (WHERE method = 'promptpay') AS promptpay_max_burst_id, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN method = 'paypal' THEN 1 END), 0), 2) AS burst_id_per_paypal, COUNT_IF(method = 'paypal') AS paypal_events, MAX(burst_id) FILTER (WHERE method = 'card') AS card_max_burst_id, PERCENTILE_APPROX(burst_id, 0.9) AS burst_id_p90 FROM sessions_payments GROUP BY 1, 2
